import React, { useState } from 'react';
import { fetchUserCount } from '../../../modules/user/services'; // Adjust the import path if necessary

const UserCountQuickBoardPlugin: React.FC = () => {
  const [userCount, setUserCount] = useState<number | null>(null);

  const handleFetchClick = async () => {
    try {
      const count = await fetchUserCount();
      setUserCount(count);
    } catch (error) {
      console.error('Error fetching user count:', error);
      setUserCount(null); // Or set an error state
    }
  };

  return (
    <div>
      <h3>User Count</h3>
      <button onClick={handleFetchClick}>Fetch User Count</button>
      <p>{userCount !== null ? `User Count: ${userCount}` : 'Click the button to fetch the user count.'}</p>
    </div>
  );
};

export default UserCountQuickBoardPlugin;